// src/App.js (Updated)
import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { auth, db } from './firebase/config';
import Header from './components/Header';
import Footer from './components/Footer';
import LandingPage from './components/LandingPage';
import Login from './components/Login';
import Signup from './components/Signup';
import Dashboard from './components/Dashboard';
import FAQ from './components/FAQ';
import ContactUs from './components/ContactUs';
import './styles/App.css';

function App() {
  const [currentPage, setCurrentPage] = useState('landing');
  const [user, setUser] = useState(null);
  const [language, setLanguage] = useState('hindi');
  const [usersCount, setUsersCount] = useState(1250);
  const [loading, setLoading] = useState(true);

  // Firebase auth state observer
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        // User signed in, fetch user data from Firestore
        try {
          const userDoc = await getDoc(doc(db, 'users', firebaseUser.uid));
          if (userDoc.exists()) {
            setUser(userDoc.data());
          }
        } catch (error) {
          console.error('Error fetching user data:', error);
        }
      } else {
        // User signed out
        setUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleLogin = (userData) => {
    setUser(userData);
    setCurrentPage('dashboard');
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
      setUser(null);
      setCurrentPage('landing');
    } catch (error) {
      console.error('Logout error:', error);
    }
  };

  const toggleLanguage = () => {
    setLanguage(language === 'hindi' ? 'english' : 'hindi');
  };

  // Simulate increasing user count
  useEffect(() => {
    const interval = setInterval(() => {
      setUsersCount(prev => prev + Math.floor(Math.random() * 5));
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const renderPage = () => {
    if (loading) {
      return <div className="loading-spinner">Loading...</div>;
    }

    switch(currentPage) {
      case 'landing':
        return <LandingPage 
                 setCurrentPage={setCurrentPage} 
                 language={language} 
                 usersCount={usersCount} 
               />;
      case 'login':
        return <Login 
                 setCurrentPage={setCurrentPage} 
                 onLogin={handleLogin} 
                 language={language} 
               />;
      case 'signup':
        return <Signup 
                 setCurrentPage={setCurrentPage} 
                 onLogin={handleLogin} 
                 language={language} 
               />;
      case 'dashboard':
        return user ? 
          <Dashboard 
            user={user} 
            language={language} 
            usersCount={usersCount} 
          /> : 
          <LandingPage setCurrentPage={setCurrentPage} language={language} />;
      case 'faq':
        return <FAQ language={language} />;
      case 'contact':
        return <ContactUs language={language} />;
      default:
        return <LandingPage setCurrentPage={setCurrentPage} language={language} />;
    }
  };

  return (
    <div className="App">
      <Header 
        currentPage={currentPage}
        setCurrentPage={setCurrentPage}
        user={user}
        onLogout={handleLogout}
        language={language}
        toggleLanguage={toggleLanguage}
        usersCount={usersCount}
      />
      <main>
        {renderPage()}
      </main>
      <Footer language={language} />
    </div>
  );
}

export default App;
